const fs = require("node:fs")
const b = fs.readFileSync("evaluations/run-11/sample.mp4")
function boxes(lo, hi) {
  const r = {}
  for (let p = lo; p + 8 <= hi;) {
    const size = b.readUInt32BE(p), name = b.toString("ascii", p + 4, p + 8)
    if (size < 8) break
    ;(r[name] ??= []).push([p + 8, p + size])
    p += size
  }
  return r
}
const top = boxes(0, b.length)
for (const range of boxes(...top.moov[0]).trak) {
  const track = boxes(...range), media = boxes(...track.mdia[0])
